In the applications screen we need to use the Dropdown component 2 times ( which means that for each component we need to duplicate the code and also the way how events are handled. The same may apply to LocaleSelectors ( and maybe we can find a way to unify the code.
Here's an example about how the code would look like with this widget:
{code:html}
import * as React from 'react';
import {DropdownWrapper} from '../../widgets/DropdownWrapper';
let dropdownSearchList = [
 <DropdownItem key="item-1">Item</DropdownItem>,
 <DropdownItem key="item-2">Item 2</DropdownItem>,
 <DropdownItem key="item-3">Item 3</DropdownItem>,
 <DropdownItem isDisabled key="name">
 Item 4
 </DropdownItem>
];
export interface ApplicationsPageProps {
}
export class ApplicationsPage extends React.Component<ApplicationsPageProps> {

 public constructor(props: ApplicationsPageProps) {
 super(props);
 }
 private doSomething = () => {
 console.log("Test");
 }
public render(): React.ReactNode {
 return (
 <ContentPage title="applications">
 <DropdownWrapper
  dropdownWrapperItems={dropdownSearchList}
  onDropdownSelect={this.doSomething}
 />
 </ContentPage>
 );
 }
